def transform(grid):
    h,w=len(grid),len(grid[0])
    cnt={}
    for row in grid:
        for x in row: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=cnt.get)
    bars=[]
    for r in range(h):
        for c in range(w-2):
            if grid[r][c]==grid[r][c+1]==grid[r][c+2] and grid[r][c]!=bg:
                # only runs on outer edges; extend full run
                end=c+2
                while end+1<w and grid[r][end+1]==grid[r][c]: end+=1
                bars.append((r,c,end,'h',grid[r][c]))
    # locate isolated dots; infer horizontal translation between two bars
    if len(bars)<2: return [row[:] for row in grid]
    b1,b2=bars[0],bars[1]
    # identify points not part of bars
    barcells={(r,c+i) for r,a,z,d,col in bars for i in range(z-a+1)}
    pts=[(r,c,v) for r in range(h) for c,v in enumerate(grid[r]) if v!=bg and (r,c) not in barcells]
    out=[row[:] for row in grid]
    shift=b2[1]-b1[1]
    for r,c,v in pts:
        out[r][c]=4
        mc=c+shift
        if 0<=mc<w:
            out[r][mc]=v
        # extend marker and translated marker vertically to their nearest bar rows
        for col in (c,mc):
            if not 0<=col<w: continue
            if r>b1[0]:
                lo,hi=b1[0]+1,r
            elif r<b1[0]:
                lo,hi=r,b1[0]
            else: lo=hi=r
            # choose nearest bar endpoint according to which bar is on that side
            if r>b1[0]:
                for rr in range(b1[0]+1,r): out[rr][col]=v
            if r<b2[0]:
                for rr in range(r+1,b2[0]): out[rr][col]=v
            # generalized boundaries: connect between the two bar rows
        # More generally each point's vertical rays stop at the surrounding bars
        if b1[0] < r < b2[0]:
            for rr in range(b1[0]+1,r): out[rr][c]=v
            for rr in range(r+1,b2[0]): out[rr][mc]=v
        elif b2[0] < r < b1[0]:
            for rr in range(b2[0]+1,r): out[rr][mc]=v
            for rr in range(r+1,b1[0]): out[rr][c]=v
    return out
